name: Harness Drift Report

on:
  schedule:
    # Run daily at 02:00 UTC
    - cron: '0 2 * * *'
  workflow_dispatch:

permissions:
  contents: read
  issues: write

jobs:
  drift-report:
    name: Generate and Report Harness Drift
    runs-on: ubuntu-latest
    timeout-minutes: 30

    steps:
      - name: Checkout
        uses: actions/checkout@v6
        with:
          fetch-depth: 0

      - name: Setup Node.js
        uses: actions/setup-node@v6
        with:
          node-version: 22
          cache: npm

      - name: Install dependencies
        run: npm ci --prefer-offline --no-audit --no-fund

      - name: Run harness drift check
        id: drift_check
        run: |
          npm run repo-drift-check
          echo "drift_detected=$(npm run repo-drift-check --silent | grep -c "DRIFT DETECTED")" >> $GITHUB_ENV
          echo "drift_count=$(npm run repo-drift-check --silent | grep -c "drift:")" >> $GITHUB_ENV

      - name: Create or update drift report issue
        if: env.drift_count != '0'
        uses: actions/github-script@v8
        with:
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            // Get the current date for the report title
            const today = new Date().toISOString().split('T')[0];
            const title = `Harness Drift Report - ${today}`;

            // Check if an issue with this title already exists
            const { data: issues } = await github.rest.issues.listForRepo({
              owner,
              repo,
              state: 'open',
              creator: 'github-actions[bot]'
            });

            const existingIssue = issues.find(issue => 
              issue.title.includes('Harness Drift Report') && 
              issue.title.includes(today)
            );

            // Prepare the drift report content
            const driftReport = `## Harness Drift Report - ${today}

This report was automatically generated by the Harness Drift Check workflow.

### Drift Found:
\`\`\`
$(npm run repo-drift-check --silent)
\`\`\`

### Action Required:
Please review the drift and take corrective action to maintain architectural integrity.

### Related Files:
- \`scripts/dev/repo-drift-check.ts\`
- \`docs/engineering/harness-engineering.md\`
- \`AGENTS.md\`

> This issue will be automatically updated with future reports.`;

            if (existingIssue) {
              // Update existing issue
              await github.rest.issues.update({
                owner,
                repo,
                issue_number: existingIssue.number,
                body: driftReport
              });

              console.log(`Updated existing issue #${existingIssue.number}`);
            } else {
              // Create new issue
              const { data: newIssue } = await github.rest.issues.create({
                owner,
                repo,
                title,
                body: driftReport,
                labels: ['area: ci', 'type: maintenance']
              });

              console.log(`Created new issue #${newIssue.number}`);
            }
```

